def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);ap.add_argument('--commit',required=True);a=ap.parse_args();r=a.root;d=json.loads((r/'results/run_provenance_v81.json').read_text());d['schema']='run_provenance_v82';d['created_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();d['github_main_commit']=a.commit;d['source_alignment']='results/main_nersc_source_alignment_v41.json';d['source_alignment_sha256']=sha(r/'results/main_nersc_source_alignment_v41.json');d['stage_progress']='results/stage_progress_v26.json';d['stage_progress_sha256']=sha(r/'results/stage_progress_v26.json');d['stage8_holdout_report']='results/stage8_holdout_validation_report_v9.json';d['stage8_holdout_report_sha256']=sha(r/'results/stage8_holdout_validation_report_v9.json');d['b1_pshot_covariance_scan']='results/b1_pshot_covariance_scan_v1.json';d['b1_pshot_covariance_scan_sha256']=sha(r/'results/b1_pshot_covariance_scan_v1.json');d['batch_outputs']['source_alignment_v41']='results/main_nersc_source_alignment_v41.json';d['batch_outputs']['stage_progress_v26']='results/stage_progress_v26.json';d['batch_outputs']['stage8_holdout_report_v9']='results/stage8_holdout_validation_report_v9.json';d['batch_outputs']['b1_pshot_covariance_scan']='results/b1_pshot_covariance_scan_v1.json';d['status']='PARTIAL';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'status':d['status'],'commit':a.commit}))
